<html lang="en">

    <meta name="viewport" content="width=device-width, initial-scale=1, shrink-to-fit=no">
    <meta http-equiv='Content-Type' content='text/html; charset=UTF-8'/>


    <!-- BOOTSTRAP CSS -->
    <link rel="stylesheet" href="https://maxcdn.bootstrapcdn.com/bootstrap/4.0.0/css/bootstrap.min.css" integrity="sha384-Gn5384xqQ1aoWXA+058RXPxPg6fy4IWvTNh0E263XmFcJlSAwiGgFAW/dAiS6JXm" crossorigin="anonymous">

    <!-- HITPUB CSS -->
    <link href="https://fonts.googleapis.com/css?family=Open+Sans:400,400i,700,700i" rel="stylesheet">
    <style id="hitpub_css">
        /***********************************************
        MOSAIC BOOSTRAP OVERWRITES
        ***********************************************/
        #hitinfo .card {
            border-radius: 0;
        }
        #hitinfo button.btn-link {
            color: #fff;
            text-decoration: none;
        }


        #hitinfo button.btn-link:hover {
            text-decoration: none;
        }
        #hit ul.question-choice {
            list-style-type: none;
        }

        /***********************************************
        MOSAIC GENERAL STYLING
        ***********************************************/
        body {
            font-family: "Open Sans", "Roboto", sans-serif;
            line-height: 1.25;
        }
        textarea#feedback {
            width: 100%
        }
        input#submitButton {
            margin: auto;
            display: block;
            background-color: #2172a4;
            color: #fff;
            font-size: 1.125rem;
            padding: .5rem 1rem;
            cursor: pointer;
            border-radius: 1rem;
        }
        input#submitButton:hover {
            background-color: #06486F;
        }

        input[type="radio"] {
            cursor: pointer;
        }

        div.goal-category {
            border-bottom: solid 1px #ccc;
            padding: 1rem 1rem;
        }

        li {
            margin:0.6em;
        }

        table {
            width: 80%;
            margin: 5px;
        }

        tr {
            border:1px solid #ccc;
        }

        th {
            width:20%;
            background-color:#fff;
            font-weight:normal;
            text-align: center;
            padding:0.5em;
        }


        td {
            padding-left:20px;
            padding-right:10px;
        }




        /***********************************************
        HIT CUSTOM GENERAL STYLING
        ***********************************************/
        div.card-header {
            background-color: #06486F;
        }
        div.card-header h5 {
            color: #fff !important;
        }


        .question-choice-container label.btn {
            background-color: #eee;
            border: #ccc 1px solid;
            margin-left: 0 !important;
            color: black;
        }


        .legend {
            margin-top: .33rem;
            font-weight: normal;
            padding-left: 40px;
        }
        .legend .label{
            font-style: italic;
        }

        .emphasize {
            font-weight: bold;
            color: black;
            font-style: italic;
        }

        .btn-group-container {
            align:left;
            padding:0;
        }

        .example {
            pointer-events:none;
        }

        .title {
            font-style: italic;
        }

        .entity {
            color: blue;
            font-weight: bold;
        }

        .use {
            color: purple;
            font-weight: bold;
        }

        .btn-group-xs > .btn, .btn-xs {
            padding: .4rem .4rem;
            font-size: .8rem;
            line-height: 1.2;
            border-radius: .2rem;
        }

        .card-body {
            background-color:#fbfbfb;
        }

        .concept_a {
            color: #0072B2;
            font-weight: bold;
            font-style: italic;
        }

        .concept_b {
            color: #D55E00;
            font-weight: bold;
            font-style: italic;
        }

        .concept_c {
            color: #aa00d5;
            font-weight: bold;
            font-style: italic;
        }

        .concept_d {
            color: #008d4b;
            font-weight: bold;
            font-style: italic;
        }

        .sm-bold {
            font-weight:bold;
            font-style: italic;
            font-size: 80%;
        }


        label[for="2"]:hover, label[for="2"].active {
            background-color:  #f57023 !important;
            color: white;
        }
        label[for="1"]:hover, label[for="1"].active {
            background-color: #038cb6 !important;
            color: white;
        }

        .one-background {background-color: #038cb6;}
        .two-background {background-color: #f57023;}

